import { Textarea } from "@/components/ui/textarea";
import { NativeSelect } from "@/components/ui/native-select";
import { standardAmal, mastooraatAmal } from "@/lib/amaal";
import { jamaatScopes } from "@/lib/jamaat-permissions";
