    {kind==="jamaat"&&<><Field label="Jamaat name" name="title" required/><SelectField label="Jamaat type" name="jamaatKind" options={[["regular","Regular"],["mastooraat","Mastooraat Jamaat"]]}/><div className="two-fields"><Field label="Start date" name="startAt" type="date" required defaultValue={fieldDate}/><Field label="End date" name="endAt" type="date" required defaultValue={modal.endDate||fieldDate}/></div><Field label="Route or destination" name="route"/><label className="check-line"><input type="checkbox" name="selfAmeer" defaultChecked/><UiCopy id="inline.requestToBeThisJamaatsAmeer" before={" "}/></label></>}
    {(kind==="person"||kind==="draftPerson")&&<><Field label="Full name" name="name" required/><Field label="Phone (optional)" name="phone" type="tel"/><Field label="Email (optional)" name="email" type="email"/>{kind==="draftPerson"&&<p className="form-hint"><UiCopy id="inline.thisPersonJoinsThisDraftRosterOnly"/></p>}</>}
    {kind==="contactCorrection"&&contactTarget&&<><Field label="Full name" name="name" required defaultValue={contactTarget.name}/><Field label="Phone (optional)" name="phone" type="tel" defaultValue={contactTarget.phone||""}/><Field label="Email (optional)" name="email" type="email" defaultValue={contactTarget.email||""}/></>}
    {kind==="placeMerge"&&parent&&<><p><UiCopy id="inline.theSourcePlaceStaysArchivedLinkedStays"/></p><p><strong><UiCopy id="inline.source"/></strong> {parent.title}</p><SelectField label="Merge into" name="targetId" options={options(objects.filter(row=>row.kind==="place"&&row.status!=="archived"&&row.id!==parent.id),"Choose destination")}/><TextField label="Reason for merge" name="reason"/></>}
