    {kind==="place"&&<><Field label="Place name" name="title" required/><SelectField label="Type" name="type" options={[["masjid","Masjid"],["musalla","Musalla"],["centre","Centre"],["markaz","Markaz"]]}/><Field label="Address" name="address"/><TextField label="Notes" name="notes"/>{placeReview?.osmId==="custom"&&<div className="pending-note" role="alert"><p><UiCopy id="inline.possibleDuplicate" after={" "}/>{placeReview.duplicates.map(row=>row.title).join(", ")}<UiCopy id="inline.searchTheSavedPlacesBeforeAddingAnother"/></p><label className="check-line"><input type="checkbox" name="allowPotentialDuplicate"/><UiCopy id="inline.iReviewedThesePlacesAndNeedA" before={" "}/></label></div>}</>}
    {kind==="member"&&<SelectField label="Person" name="personId" options={personOptions}/>}
    {kind==="permission"&&<><p><UiCopy id="inline.permissionsFor" after={" "}/>{people.find(p=>p.id===modal.date)?.name}</p><p><UiCopy id="inline.planningAccessDoesNotIncludeContactsFunds"/></p>{jamaatScopes.map(scope=><label className="check-line" key={scope}><input type="checkbox" name={scope} defaultChecked={permissionScopes.includes(scope)}/> {t(({roster:"permission.roster",route:"permission.route",amaal:"permission.amaal",contacts:"permission.contacts",funds:"permission.funds",notes:"permission.notes",tashkil:"permission.tashkil",incidents:"permission.incidents"} as Record<string,CopyKey>)[scope])}</label>)}<Field label="Duty labels (comma separated)" name="labels" defaultValue={String((memberships.find(m=>m.jamaatId===modal.parentId&&m.personId===modal.date)?.permissions.labels as string[]|undefined)||[]).replaceAll(",",", ")} placeholder="Khidmah, Route planner"/></>}
