    {kind==="note"&&<><Field label="Note title" name="title" defaultValue="Jamaat report"/><SelectField label="Type" name="category" options={[["general","General"],["summary","How the Jamaat went"],["mashwara","Daily Mashwara"],["local-work","Local work"]]}/><TextField label="Notes" name="text"/><div className="two-fields"><Field label="People tashkiled" name="peopleTashkiled" type="number" min="0" step="1" defaultValue="0"/><Field label="Jamaats tashkiled" name="jamaatsTashkiled" type="number" min="0" step="1" defaultValue="0"/></div></>}
